function F.bowl(W)
    if not F.catOn("Bowling") or os.clock() - F.bowlAt < 6 or os.clock() - F.bowlXP < F.bowlCd then return false end
    local st = Workspace:FindFirstChild("Stunts")
    local B = st and st:FindFirstChild("Bowling")
    local pins = B and B:FindFirstChild("Pins")
    local lane = B and B:FindFirstChild("BowlingLane")
    if not (pins and lane) or #pins:GetChildren() == 0 then return false end
    for _, pn in ipairs(pins:GetChildren()) do if pn:GetPivot().UpVector.Y < 0.8 then return false end end
    F.bowlAt = os.clock()
