    task.delay(12, function()
        if F.bowlXP >= tB then F.bowlMiss = 0 F.bowlCd = 0 return end
        F.bowlMiss = (F.bowlMiss or 0) + 1
        if F.bowlMiss >= 2 and F.bowlXP > 0 then F.bowlCd = math.min(40, tB - F.bowlXP + 3) LOG("bowl cd", F.bowlCd) end
    end)
    S.task = __T["Bowling a strike"] S.taskAt = os.clock()
