function F.smash()
    if not on("f_smash") then return false end
    if not F.ensureWorm() then S.task = __T["Turning into a worm"] S.taskAt = os.clock() return true end
    local W = F.ws()
    if not W then S.task = __T["Finding your worm"] S.taskAt = os.clock() return true end
    F.readQuests()
    local e = F.pick(W.pos)
    if not (e and e.ev) and (F.bowl(W) or F.rings(W) or F.ramps(W)) then return true end
    local ep = on("s_elder") and F.elder()
    if ep then S.elderSeen = true end
    if ep and Vector2.new(W.pos.X - ep.X, W.pos.Z - ep.Z).Magnitude < val("s_elderd", 160) and not e then
        local away = Vector3.new(W.pos.X - ep.X, 0, W.pos.Z - ep.Z)
        away = away.Magnitude > 0.1 and away.Unit or Vector3.new(1, 0, 0)
        local dest = W.pos + away * (val("s_elderd", 160) + 40)
        F.place(W, Vector3.new(dest.X, (M.ground(dest) or W.pos.Y) + 4, dest.Z), away, 4)
        S.task = __T["Dodging the Elder Worm"] S.taskAt = os.clock()
        return true
    end
    if not e then return false end
    S.task = (e.ev and __T["Event: "] or __T["Smashing "]) .. tostring(e.m.Name):gsub("[_%d]+.*$", "")
    S.taskAt = os.clock()
    local tH = os.clock()
    local got, broke = F.hit(e, W)
    if e.cat == "Players" or e.ev or e.cat == "Chests" then LOG("target", e.cat, e.m.Name, got, broke, string.format("%.1fs", os.clock() - tH)) end
    local k = F.key(e)
    local L = F.learn[k] or { tries = 0, xp = 0, xpr = 0, time = 0 }
    F.learn[k] = L
    L.time = (L.time or 0) * 0.97 + (os.clock() - tH)
    L.xpr = (L.xpr or 0) * 0.97 + math.max(got or 0, broke and e.value or 0)
    L.tries += 1 L.xp += (got or 0) + (broke and 1 or 0)
    if L.tries >= 6 and L.xp == 0 and not F.seenKind[F.xpKey(e)] then L.waitT = os.clock() + 180 L.tries = 0 LOG("no xp from", k) end
    if (got or 0) > 0 then
        F.fails[e.m] = nil
        F.skipUntil[e.m] = os.clock() + ((e.cat == "Players" or e.cat == "People") and 3 or 25)
        if e.cat == "People" or e.cat == "Animals" then S.eaten += 1 elseif e.cat == "Players" then S.players += 1 elseif e.cat == "Chests" then S.chests += 1 else S.smashed += 1 end
        if e.ev then S.events += 1 end
    elseif broke then
        if e.m:GetAttribute("Burning") == true and not F.burnTry[e.m] then F.burnTry[e.m] = true else F.burnTry[e.m] = nil F.skipUntil[e.m] = os.clock() + 25 end
        F.fails[e.m] = nil
        if e.cat ~= "People" and e.cat ~= "Animals" and e.cat ~= "Players" then S.smashed += 1 end
    else
        local n = (F.fails[e.m] or 0) + 1
        F.fails[e.m] = n
        F.skipUntil[e.m] = os.clock() + (e.ev and 0 or 6)
        if e.ev then n = 0 F.fails[e.m] = 0 end
        if n >= 2 then F.skipUntil[e.m] = os.clock() + (e.cat == "Players" and 20 or 40) F.fails[e.m] = 0 end
    end
    return true
end
