            if type(s) == "table" and type(s.id) == "string" then
                local ok, can = pcall(C.canUse, lp, s.id)
                if ok and can and (not best or (s.order or 0) > (best.order or 0)) then best = s end
            end
        end
    end
    for _, v in pairs(C) do if type(v) == "table" and v ~= C.passSkins then local f = v[1] if type(f) == "table" and f.id then scan(v) end end end
    return best
end
function F.skinList()
