task.spawn(function()
    while RUNNING do
        pcall(function()
            local busy = (os.clock() - (S.taskAt or 0) < 3) and S.task or (on("f_smash") and __T["Looking for targets"] or __T["Idle"])
            if not M.isWorm() and on("f_smash") then busy = __T["Turning into a worm"] end
            setText(UI.s1, "<b>" .. busy .. "</b>")
            local rate = F.xpRate()
            setText(UI.s2, string.format(__T["Level <b>%s</b> · %s/%s XP"], tostring(M.attr("Level", 1)), M.fmt(M.attr("Xp", 0)), M.fmt(M.attr("XpNeed", 0))))
            setText(UI.s3, string.format(__T["XP/min <b>%s</b>"], rate and M.fmt(rate) or "..."))
            setText(UI.s4, string.format(__T["Smashed %d · Eaten %d · Strikes %d\nPlayers %d · Events %d · Chests %d"], S.smashed, S.eaten, S.bowls or 0, S.players, S.events, S.chests))
            local nm = D.Skins and D.Skins.nameOf and select(2, pcall(D.Skins.nameOf, lp:GetAttribute("WormSkin"))) or lp:GetAttribute("WormSkin")
            local lvl = tonumber(M.attr("Level", 1)) or 1
            S.lvl0 = S.lvl0 or lvl
            S.xpT0 = S.xpT0 or M.attr("XpTotal", 0)
            local nxt
            for _, sk in ipairs(F.skinList()) do if sk.level and sk.level > lvl and (not nxt or sk.level < nxt.level) then nxt = sk end end
            setText(UI.p1, string.format(__T["Worm <b>%s</b>\nNext: %s\nSession <b>+%s XP</b> · +%d lv\n%s / %s XP"], tostring(nm or "-"), nxt and (nxt.name .. __T[" · Lv "] .. nxt.level) or __T["all unlocked"], M.fmt(M.attr("XpTotal", 0) - S.xpT0), lvl - S.lvl0, M.fmt(M.attr("Xp", 0)), M.fmt(M.attr("XpNeed", 0))))
        end)
        task.wait(1)
    end
end)
